params.code:
// one signed distance per sample, in plain arithmetic (no vectors, no rand(): this runs for every sample of the mesh)
const L = body_size, fsz = Math.max(feature_size, L / 50);  // x, y, z: the sample point; fsz: the mesh's edge length
const hash = (n) => { let h = Math.imul(n + 0x9e3779b9, 0x85ebca6b) ^ Math.imul(seed + 0x27d4eb2f, 0xc2b2ae35); h = Math.imul(h ^ (h >>> 15), 0x2c1b873b); h = Math.imul(h ^ (h >>> 13), 0x297a2d39); return ((h ^ (h >>> 16)) >>> 0) / 4294967296; };
const sm = (a, b, k) => { const h = Math.max(k - Math.abs(a - b), 0) / k; return Math.min(a, b) - h * h * k * 0.25; };
const ell = (px, py, pz, a, b, c) => {
  const k0 = Math.sqrt((px / a) ** 2 + (py / b) ** 2 + (pz / c) ** 2), k1 = Math.sqrt((px / (a * a)) ** 2 + (py / (b * b)) ** 2 + (pz / (c * c)) ** 2);
  return k1 > 1e-9 ? k0 * (k0 - 1) / k1 : -Math.min(a, b, c);
};
// a capsule from a (radius ra) to b (radius rb)
const cap = (ax, ay, az, bx, by, bz, ra, rb) => {
  const pax = x - ax, pay = y - ay, paz = z - az, bax = bx - ax, bay = by - ay, baz = bz - az;
  const h = Math.max(0, Math.min(1, (pax * bax + pay * bay + paz * baz) / (bax * bax + bay * bay + baz * baz)));
  const dx = pax - bax * h, dy = pay - bay * h, dz = paz - baz * h;
  return Math.sqrt(dx * dx + dy * dy + dz * dz) - (ra + (rb - ra) * h);
};
const sph = (cx, cy, cz, r) => Math.sqrt((x - cx) ** 2 + (y - cy) ** 2 + (z - cz) ** 2) - r;
// the soles are cut off at the ground with edges rounded over k (at least the edge length: a sharper rim meshes with
// spikes); the creature stands k lower, so the rounding does not shorten the legs
const k = Math.max(0.02 * L, fsz);
y += k;  // from here on, y is measured from k below the ground
// parts melt together over blend, never sharper than the mesh can show: closer than its edge length, they join
const kb = Math.max(blend, 2 * fsz), kf = Math.max(0.5 * blend, 2 * fsz);
// body: an egg along X (the creature faces +X), its belly 0.24 body_size up (0.24 body_size - k above the ground)
const rx = 0.5 * L, ry = 0.34 * L, rz = 0.38 * L, cy = 0.24 * L + ry;
let d = ell(x, y - cy, z, rx, ry, rz);
// a round head in front, on top
const rh = 0.38 * L * head;
d = sm(d, sph(0.42 * L + 0.55 * rh, cy + 0.28 * L + 0.3 * rh, 0, rh), kb);
// stubby legs around the belly, each on a flat foot (slimmer when there are many); the seed moves the feet a little.
// Legs, feet and tail are never thinner than two edge lengths (thinner parts mesh as loose bits or folds)
const slim = Math.min(1, Math.sqrt(4 / legs)), thin = fsz, rl = Math.max(0.085 * L * slim, thin), rf = Math.max(0.11 * L * slim, 1.25 * thin);
for (let i = 0; i < legs; i++) {
  const a = (i + 0.5) * 2 * Math.PI / legs, hx = 0.6 * rx * Math.cos(a), hz = 0.62 * rz * Math.sin(a), hy = cy - 0.45 * ry;
  const fx = hx * 1.15 + (hash(i * 2) - 0.5) * 0.14 * L, fz = hz * 1.25 + (hash(i * 2 + 1) - 0.5) * 0.1 * L, fy = 0.55 * rf;
  d = sm(d, cap(hx, hy, hz, fx, fy, fz, rl, rl), kb);
  d = sm(d, ell(x - fx - 0.03 * L, y - fy, z - fz, 1.3 * rf, 0.8 * rf, rf), kf);
}
// tail: five tapering segments curling up behind, 0.9 tail body lengths long
if (tail > 0) {
  const s = 0.18 * tail * L;
  let ax = -0.85 * rx, ay = cy, ra = Math.max(0.12 * L, thin), t = Infinity;
  for (let i = 0; i < 5; i++) {
    const th = (165 - 15 * i) * Math.PI / 180, bx = ax + s * Math.cos(th), by = ay + s * Math.sin(th), rb = Math.max(0.8 * ra, thin);
    t = Math.min(t, cap(ax, ay, 0, bx, by, 0, ra, rb));
    ax = bx; ay = by; ra = rb;
  }
  d = sm(d, t, kb);
}
// a few soft lumps on the back, a little more than half out of the skin
if (bumps > 0) {
  const n = Math.round(2 + 8 * bumps);
  for (let j = 0; j < n; j++) {
    const t = hash(100 + j) * 2 * Math.PI, ph = 0.2 + hash(200 + j) * 0.9, rb = L * (0.06 + 0.05 * hash(300 + j)) * (0.6 + 0.4 * bumps);
    const sx = rx * Math.cos(ph) * Math.cos(t), sy = ry * Math.sin(ph), sz = rz * Math.cos(ph) * Math.sin(t), f = 1 - 0.4 * rb / Math.sqrt(sx * sx + sy * sy + sz * sz);
    d = sm(d, sph(f * sx, cy + f * sy, f * sz, rb), 0.65 * rb);
  }
}
// flat soles: cut softly at the ground
const g = k - y, h = Math.max(k - Math.abs(d - g), 0) / k;
return Math.max(d, g) + h * h * k * 0.25;

// how far apart the points near the ground lie (the soles of the feet)
const near = 0.5 * Math.max(feature_size, body_size / 50);
let x0 = Infinity, x1 = -Infinity, z0 = Infinity, z1 = -Infinity;
for (let i = 0; i < npoints(0); i++) {
  const q = point(0, 'P', i);
  if (q[1] < near) { x0 = Math.min(x0, q[0]); x1 = Math.max(x1, q[0]); z0 = Math.min(z0, q[2]); z1 = Math.max(z1, q[2]); }
}
f@ground_span = x1 >= x0 ? Math.max(x1 - x0, z1 - z0) : 0;
